//! The third-party notices (#1784) are checked in every bundle, at the one path that writes
//! them, and only on a build whose source was written for that check.
//!
//! The notices are generated by `vite build` into `app/dist/THIRD-PARTY-NOTICES`
//! (`tools/third-party-notices.mjs`, `app/vite.config.ts`), copied into each bundle by
//! `tauri.release.conf.json`, and checked there by `release.yml`. Three files name one path, so
//! a rename in one of them is caught here and not on the next release run.
//!
//! And a `workflow_run` executes `main`'s `release.yml` over the source of the commit whose
//! `ci` went green, which is older when a merge lands mid-`ci`. The notices' check failed its
//! first dev run that way: run 38189104321 executed `release.yml` from 37ec362e, which added the
//! check, over fc7131dd, which predates the notices, and `grep` found no file. `plan` now
//! builds nothing when the two `release.yml`s differ.

use crate::workflow;

use std::path::PathBuf;

use workflow::{Job, job, release_jobs, run_lines, step_uses, step_value};

const NOTICES: &str = "THIRD-PARTY-NOTICES";

fn repo(path: &str) -> String {
    let at = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .join(path);
    workflow::read(&at)
}

fn step(job: &Job, name: &str) -> Vec<String> {
    job.steps()
        .into_iter()
        .find(|s| s[0].trim() == format!("- name: {name}"))
        .unwrap_or_else(|| panic!("job `{}` has no step `{name}`", job.name))
}

#[test]
fn the_generator_the_bundler_and_the_check_name_one_notices_file() {
    // The generator names the file, and vite writes it at the top of the window's build.
    assert!(
        repo("tools/third-party-notices.mjs")
            .contains(&format!("export const NOTICES_FILE = \"{NOTICES}\";")),
        "tools/third-party-notices.mjs no longer calls the notices `{NOTICES}`"
    );
    let vite = repo("app/vite.config.ts");
    assert!(
        vite.contains("this.emitFile({ type: \"asset\", fileName: NOTICES_FILE,"),
        "app/vite.config.ts no longer writes the notices into the build"
    );
    assert!(
        !vite.contains("outDir"),
        "app/vite.config.ts moves the build out of `app/dist`, where the bundler and the check read it"
    );
    let tauri: serde_json::Value =
        serde_json::from_str(&repo("app/src-tauri/tauri.conf.json")).expect("tauri.conf.json");
    assert_eq!(tauri["build"]["frontendDist"], "../dist");

    // The bundler copies it from there to the top of the bundle's resources.
    let release: serde_json::Value =
        serde_json::from_str(&repo("app/src-tauri/tauri.release.conf.json"))
            .expect("tauri.release.conf.json");
    let resources = &release["bundle"]["resources"];
    assert_eq!(
        resources[format!("../dist/{NOTICES}")],
        NOTICES,
        "{resources}"
    );
    for own in ["LICENSE", "NOTICE"] {
        assert_eq!(resources[format!("../../{own}")], own, "{resources}");
    }

    // And the release checks it at that path, in the build and in each platform's bundle.
    let jobs = release_jobs();
    let lines = run_lines(&step(
        job(&jobs, "build"),
        "The bundle carries purlis's LICENSE and NOTICE, and the third-party notices",
    ));
    for want in [
        format!("grep -q '^tauri [0-9][^ ]* (Rust crate' app/dist/{NOTICES}"),
        format!("grep -q '^react [0-9][^ ]* (npm package' app/dist/{NOTICES}"),
        format!("cmp \"$resources/{NOTICES}\" app/dist/{NOTICES}"),
        format!("grep -q 'usr/lib/purlis/{NOTICES}$' <<<\"$listing\""),
        "set -euo pipefail".to_owned(),
    ] {
        assert!(
            lines.contains(&want),
            "the check lacks `{want}`: {lines:#?}"
        );
    }
}

#[test]
fn a_green_ci_whose_source_runs_another_release_workflow_builds_nothing() {
    let jobs = release_jobs();
    let plan = job(&jobs, "plan");
    let steps = plan.steps();

    // The source, at the commit whose `ci` went green.
    assert_eq!(
        step_value(&steps[0], "with", "ref"),
        Some("${{ github.event.workflow_run.head_sha || github.sha }}")
    );
    // And beside it, the `release.yml` this run executes, alone.
    let running = &steps[1];
    assert!(
        step_uses(running).is_some_and(|u| u.starts_with("actions/checkout@")),
        "{running:#?}"
    );
    assert_eq!(
        step_value(running, "with", "ref"),
        Some("${{ github.workflow_sha }}")
    );
    assert_eq!(step_value(running, "with", "path"), Some("running"));
    assert_eq!(
        step_value(running, "with", "sparse-checkout"),
        Some(".github/workflows/release.yml")
    );
    assert_eq!(
        step_value(running, "with", "persist-credentials"),
        Some("false")
    );

    // A `workflow_run` whose two files differ skips the build and publishes nothing.
    let lines = run_lines(&step(
        plan,
        "Channel, version, and whether anything is published",
    ));
    let compare = lines
        .iter()
        .position(|l| {
            l == "if [ \"$EVENT\" = workflow_run ] && ! cmp -s running/.github/workflows/release.yml .github/workflows/release.yml; then"
        })
        .unwrap_or_else(|| panic!("plan does not compare the two release.yml: {lines:#?}"));
    assert_eq!(lines[compare + 2], "skip=true; publish=false", "{lines:#?}");
    assert_eq!(lines[compare + 3], "fi");

    // And `skip` is what keeps every build from starting.
    assert_eq!(
        job(&jobs, "build").condition(),
        Some("needs.plan.outputs.skip != 'true'")
    );
}
